<script setup>
import { onMounted, ref, watch } from 'vue'
import { RouterLink } from 'vue-router'
import ResultsPanel from '../components/results/ResultsPanel.vue'
import BenchmarkCharts from '../components/results/BenchmarkCharts.vue'
import { benchmarkSession } from '../services/benchmarkSession.js'
import { exportHistoryCsv, getBenchmarkDetail, getBenchmarkHistory, historyItemToResult } from '../services/benchmarkService.js'

const history = ref([]); const loading = ref(true); const error = ref(''); const selected = ref(null); const exporting = ref(false); const exportMessage = ref('')
async function loadHistory() { loading.value = true; error.value = ''; try { const data = await getBenchmarkHistory(); history.value = data.items || [] } catch (err) { error.value = err.message } finally { loading.value = false } }
async function selectItem(item) { try { selected.value = historyItemToResult(await getBenchmarkDetail(item.id)) } catch (err) { error.value = err.message } }
async function exportCsv() { exporting.value = true; exportMessage.value = ''; try { const filename = await exportHistoryCsv(); exportMessage.value = `Export berhasil: ${filename}` } catch (err) { exportMessage.value = err.message } finally { exporting.value = false } }
function summary(item, type) { const data = item.tcp_result || item.udp_result; if (!data) return '—'; if (type === 'rtt') return data.latency?.average == null ? '—' : `${Number(data.latency.average).toFixed(2)} ms`; if (type === 'throughput') return `${(Number(data.throughput?.bytesPerSecond || 0) / 1024).toFixed(2)} KB/s`; return `${Number(data.packetLossRate || 0).toFixed(2)}%` }
watch(() => benchmarkSession.result, loadHistory)
onMounted(loadHistory)
</script>

<template>
  <main class="main-content"><div class="page-intro"><div><p class="eyebrow">PERSISTED HISTORY</p><h1>Results</h1><p class="intro-copy">Benchmark results stored locally in SQLite and available after restart.</p></div><RouterLink class="text-link" to="/benchmark">Back to benchmark</RouterLink></div><div v-if="error" class="alert error-alert"><strong>History could not be loaded</strong><span>{{ error }}</span><button class="inline-button" @click="loadHistory">Retry</button></div><div v-if="exportMessage" class="alert" :class="exportMessage.startsWith('Export berhasil') ? 'success-alert' : 'error-alert'"><strong>CSV export</strong><span>{{ exportMessage }}</span></div><section v-if="loading" class="loading-state panel"><span class="loading-bars"><i></i><i></i><i></i></span><h2>Loading history</h2><p>Reading saved benchmark results from the backend.</p></section><section v-else-if="!history.length" class="empty-state panel"><div class="empty-visual"><span></span><span></span><span></span></div><h2>No saved results</h2><p>Complete a benchmark to create the first local history record. CSV export is unavailable until history exists.</p><RouterLink class="primary-button" to="/benchmark">Go to benchmark</RouterLink></section><template v-else><section class="history-panel panel"><div class="table-title"><div><p class="eyebrow">LOCAL SQLITE HISTORY</p><h3>Completed benchmarks</h3></div><div class="history-actions"><button class="refresh-button" @click="loadHistory">Refresh</button><button class="primary-button export-button" :disabled="exporting" @click="exportCsv">{{ exporting ? 'Exporting...' : 'Export CSV' }}</button></div></div><div class="table-wrap"><table><thead><tr><th>Test ID</th><th>Created</th><th>Protocol</th><th>Packets</th><th>Payload</th><th>Average RTT</th><th>Throughput</th><th>Loss</th><th></th></tr></thead><tbody><tr v-for="item in history" :key="item.id"><td class="mono-cell">{{ item.test_id }}</td><td>{{ new Date(item.created_at).toLocaleString() }}</td><td><span class="protocol-pill" :class="item.protocol === 'TCP' ? 'tcp' : item.protocol === 'UDP' ? 'udp' : 'both'">{{ item.protocol }}</span></td><td>{{ item.packet_count }}</td><td>{{ item.payload_size }} B</td><td>{{ summary(item, 'rtt') }}</td><td>{{ summary(item, 'throughput') }}</td><td>{{ summary(item, 'loss') }}</td><td><button class="detail-button" @click="selectItem(item)">View</button></td></tr></tbody></table></div></section><section v-if="selected" class="history-detail"><ResultsPanel :result="selected" /><BenchmarkCharts :result="selected" /></section></template></main>
</template>
